@app.cell(hide_code=True)
def _(Path, mo, os, runner_commit, subprocess, variants):
    _configured = os.environ.get("FORGE_RUNNER_ROOT", "")
    _ready = False
    _reason = "No shared coordinator is configured in this runtime."
    if _configured and Path(_configured).is_absolute():
        try:
            _actual = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=_configured, text=True, stderr=subprocess.DEVNULL).strip()
            _ready = _actual == runner_commit and bool(os.environ.get("WANDB_API_KEY")) and (Path(_configured) / "forge/local-results/budget.json").exists() and (Path(_configured) / "forge/node_modules/tsx/dist/loader.mjs").exists()
            _reason = "Coordinator prerequisites found; the runner will recheck qualification and the ledger before work." if _ready else "Coordinator revision, credential, pinned dependencies, or durable ledger is missing."
        except (OSError, subprocess.CalledProcessError):
            _reason = "The configured coordinator cannot be read."
    runner_root = mo.ui.text(value=_configured, disabled=True, label="Coordinator set by FORGE_RUNNER_ROOT", full_width=True)
    entity = mo.ui.text(value=os.environ.get("WANDB_ENTITY", "wandb"), label="W&B team")
    result_project = mo.ui.text(value=os.environ.get("WANDB_PROJECT", "learn-harness-engineering-forge"), label="Private results project")
    treatment = mo.ui.dropdown(options=variants, value=variants[0], label="Adapted Forge treatment")
    repetitions = mo.ui.number(start=1, stop=3, value=1, label="Repeats (Projects 01–06)")
    launch = mo.ui.button(value=0, on_click=lambda value: value + 1, disabled=not _ready, label="Launch paid adapted rerun")
    get_execution, set_execution = mo.state({"click": 0, "status": "Not launched"})
    mo.accordion({"Optional paid rerun · instructor coordinator required": mo.vstack([
        mo.md("This reruns the recorded Forge adaptation, not all of the original course lab. A fresh hosted notebook has no coordinator mounted by default. Set FORGE_RUNNER_ROOT and external credentials before starting this notebook to enable the button. The shared ledger, exact pinned revision, and qualification are required.\n\nProject 07 uses a one-round demonstration, not the two-hour/five-round assignment. Project 08 pauses at human approval; this notebook does not submit a decision.\n\n**Readiness:** " + _reason), runner_root, entity, result_project, treatment, repetitions, launch
    ])})
    return (
        entity,
        get_execution,
        launch,
        repetitions,
        result_project,
        runner_root,
        set_execution,
        treatment,
    )


@app.cell(hide_code=True)
def _(
    Path,
    entity,
    get_execution,
    json,
    launch,
    mo,
    os,
    project_id,
    repetitions,
    result_project,
    runner_commit,
    runner_root,
    set_execution,
    subprocess,
    treatment,
    uuid,
):
    mo.stop(launch.value <= get_execution()["click"])
    set_execution({"click": launch.value, "status": "Starting explicit request"})
    try:
        _root = Path(runner_root.value)
        if not runner_root.value or not _root.is_absolute():
            raise RuntimeError("Configure an absolute shared coordinator checkout first.")
        _actual = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=_root, text=True).strip()
        if _actual != runner_commit:
            raise RuntimeError("The coordinator revision must match the pinned runner revision shown above.")
        _ledger = _root / "forge/local-results/budget.json"
        if not _ledger.exists():
            raise RuntimeError("A qualified, durable shared budget ledger is required; no new ledger is created here.")
        _budget = json.loads(_ledger.read_text())
        if _budget.get("halted"):
            raise RuntimeError("The shared ledger is halted; reconcile its recorded reason before launching.")
        _authorized_limit = _budget.get("limitUsd")
        if _authorized_limit is None and not _budget.get("authorizations"):
            raise RuntimeError("An unlimited ledger requires its recorded explicit authorization.")
        _env = dict(os.environ, WANDB_ENTITY=entity.value, WANDB_PROJECT=result_project.value, FORGE_BUDGET_USD="unlimited" if _authorized_limit is None else str(_authorized_limit))
        if not _env.get("WANDB_API_KEY"):
            raise RuntimeError("Supply credentials through the coordinator environment, never a notebook cell.")
        _command = ["node", "--import", str(_root / "forge/node_modules/tsx/dist/loader.mjs"), str(_root / "forge/src/cli.ts")]
        _checkpoint = str(_root / "forge/local-results" / ("notebook-" + uuid.uuid4().hex + ".json"))
        if project_id == "project-07":
            _command += ["loop", "--mode", treatment.value, "--checkpoint", _checkpoint, "--duration-seconds", "600", "--max-rounds", "1", "--execute"]
        elif project_id == "project-08":
            _command += ["graph", "--checkpoint", _checkpoint, "--execute"]
        else:
            _command += ["compare", "--project", "project-01" if project_id == "overview" else project_id, "--variant", treatment.value, "--repeats", str(int(repetitions.value)), "--source", runner_commit, "--execute"]
        _completed = subprocess.run(_command, cwd=_root, env=_env, text=True, capture_output=True, timeout=3500)
        set_execution({"click": launch.value, "status": "Runner finished", "exit_code": _completed.returncode, "stdout": _completed.stdout[-16000:], "stderr": _completed.stderr[-4000:]})
    except Exception as _error:
        set_execution({"click": launch.value, "status": "Not completed", "error": str(_error)})
    return


